import{_ as e,c as r,o as a,ae as s}from"./chunks/framework.DI6M9D4h.js";const m=JSON.parse('{"title":"Kimiko","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/kimiko/README.md","filePath":"build-guides/kimiko/README.md","lastUpdated":1754310023000}'),d={name:"build-guides/kimiko/README.md"};function o(i,t,l,p,n,c){return a(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="kimiko" tabindex="-1">Kimiko <a class="header-anchor" href="#kimiko" aria-label="Permalink to &quot;Kimiko&quot;">​</a></h1><p><a href="https://github.com/firstcontributions/first-contributions" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/PRs-welcome-brightgreen.svg?style=flat-square" alt="PRs Welcome" loading="lazy"></a><a href="https://discord.gg/frjFXZB" title="Redirect to Keycapsss Discord" target="_blank" rel="noreferrer"><img src="https://img.shields.io/discord/548530462419582996?style=flat-square&amp;logo=discord&amp;logoColor=white" alt="Discord" loading="lazy"></a><a href="https://creativecommons.org/licenses/by-nc-sa/4.0/" target="_blank" rel="noreferrer"><img src="https://img.shields.io/badge/License-CC%20BY--NC--SA%204.0-lightgrey.svg?style=flat-square" alt="License: CC BY-NC-SA 4.0" loading="lazy"></a></p><ul><li>Aggressive staggered pinky rows</li><li>Support for one rotary encoder per side (two possible positions)</li><li>Per key RGB led with SK6812 Mini-E led (with legs, easy to solder)</li><li>Support for MX switches (Hotswap sockets)</li></ul><p><strong><a href="./buildguide_en.html">Build-Guide</a></strong></p><p><strong><a href="./Keymap.html">Keymap-Guide</a></strong></p><p><strong>Hardware available at <a href="https://keycapsss.com" target="_blank" rel="noreferrer">keycapsss.com</a></strong></p><p><img src="https://keycapsss.com/media/image/g0/9e/1f/kimiko-split-keyboard-1vUUb4KAeC3ojx_1280x1280.jpg" alt="Kimiko keyboard with RGB LED" loading="lazy"></p><h2 id="parts" tabindex="-1">Parts <a class="header-anchor" href="#parts" aria-label="Permalink to &quot;Parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part name</th><th>Quantity</th><th>Remarks</th><th>Photo</th></tr></thead><tbody><tr><td>Kimiko PCB</td><td>1 set</td><td></td><td></td></tr><tr><td>Kimiko case</td><td>1 set</td><td>2 solid panels, 2 with holes for switches (plates)</td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/79/arduino-pro-micro-atmega32u4-controller" target="_blank" rel="noreferrer">Pro Micro</a> or <a href="https://keycapsss.com/keyboard-parts/parts/141/puchi-c-pro-micro-replacement-with-usb-c-and-atmega32u4" target="_blank" rel="noreferrer">Puchi-C</a></td><td>2 pcs (a mix is possible)</td><td>Recommend to use <a href="https://keycapsss.com/keyboard-parts/parts/100/single-row-socket-headers-pins-mill-max-series-315" target="_blank" rel="noreferrer">Mill-Max Single Row Socket Headers</a>, to make it hot-swappable.</td><td></td></tr><tr><td>Key switch (MX)</td><td>58-60 pcs</td><td></td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/49/kailh-hot-swap-pcb-sockets-10-pcs" target="_blank" rel="noreferrer">Kailh switch socket</a></td><td>58-60 pcs</td><td></td><td></td></tr><tr><td>Diodes 1N4148W (SMD)</td><td>60 pcs</td><td></td><td></td></tr><tr><td>TRRS jack</td><td>2 pcs</td><td></td><td></td></tr><tr><td>Tactile switch</td><td>2 pcs</td><td>Reset switch</td><td></td></tr><tr><td>TRRS cable</td><td>1 cable</td><td>Must be a 4-pole cable</td><td></td></tr><tr><td>Key caps</td><td>58-60 pcs</td><td>1.5U caps, can also be 1U</td><td></td></tr><tr><td>Micro USB or USB-C cable</td><td>1 pcs</td><td>Dependent what you use on the master half.</td><td></td></tr></tbody></table><h2 id="optionally" tabindex="-1">Optionally <a class="header-anchor" href="#optionally" aria-label="Permalink to &quot;Optionally&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part name</th><th>Quantity</th><th>Remarks</th><th>Photo</th></tr></thead><tbody><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/80/ssd1306-oled-lcd-display-0.91-inch-128x32-i2c-white" target="_blank" rel="noreferrer">OLED module</a></td><td>2 pcs</td><td>It is possible to use only one display</td><td></td></tr><tr><td>SK6812 Mini-E</td><td>60 pcs</td><td>RGB LEDs for keycap backlight <strong>(underglow LEDs must be soldered, because they are connected in series)</strong></td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/59/rotary-encoder-with-switch" target="_blank" rel="noreferrer">Rotary encoder</a></td><td>0-2 pcs</td><td>One per side are supported.</td><td></td></tr><tr><td><a href="https://keycapsss.com/keyboard-parts/parts/100/single-row-socket-headers-pins-mill-max-series-315" target="_blank" rel="noreferrer">Mill-Max Single Row Socket Headers</a>, or <a href="https://keycapsss.com/keyboard-parts/parts/91/spring-loaded-pin-headers-12-pin-2pcs-conthrough" target="_blank" rel="noreferrer">Spring-loaded pin headers</a>,</td><td>4 x 12 row headers</td><td>To make pro micro Hot-swappable. Highly recommended to get the header pins too (You can use diode legs if you don&#39;t get the header pins)</td><td></td></tr></tbody></table><h2 id="case-files" tabindex="-1">Case files <a class="header-anchor" href="#case-files" aria-label="Permalink to &quot;Case files&quot;">​</a></h2><p>Drawings (SVG, DXF) for the case are located in the <a href="./plates/">plates folder</a>.</p><h2 id="firmware" tabindex="-1">Firmware <a class="header-anchor" href="#firmware" aria-label="Permalink to &quot;Firmware&quot;">​</a></h2><p>Clone/download the QMK firmware and execute the following in the <a href="https://github.com/qmk/qmk_firmware" target="_blank" rel="noreferrer">qmk_firmware</a> directory to write the default Lily58L keymap</p><pre><code>make keycapsss/kimiko:default:avrdude (for pro micro) 
</code></pre><p>When <strong><code>Detecting USB port, reset your controller now...</code></strong> is displayed, press the reset button on the keyboard to start writing. Each half of the keyboard must be programmed separately using this approach.</p><p>If you&#39;re using DFU bootloader (in case of the Puchi-C or Elite-C), replace the &#39;avrdude&#39; with &#39;dfu&#39;</p>`,18)])])}const k=e(d,[["render",o]]);export{m as __pageData,k as default};
